CREATE DATABASE IF NOT EXISTS personal_expense_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE personal_expense_management;
CREATE TABLE users(id BIGINT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE categories(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,name VARCHAR(80) NOT NULL,type ENUM('INCOME','EXPENSE') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE transactions(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,category_id BIGINT NULL,title VARCHAR(160) NOT NULL,description TEXT,amount DECIMAL(15,2) NOT NULL,type ENUM('INCOME','EXPENSE') NOT NULL,transaction_date DATE NOT NULL,payment_method VARCHAR(40),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX ix_user_date(user_id,transaction_date),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE budgets(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,category_id BIGINT NULL,monthly_limit DECIMAL(15,2) NOT NULL,month TINYINT NOT NULL,year SMALLINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);